'use strict';

class CsvError extends Error {
  constructor(message, line, column) {
    super(`${message} (line ${line}, column ${column})`);
    this.name = 'CsvError';
    this.line = line;
    this.column = column;
  }
}

function checkDelimiter(options) {
  const d = options.delimiter === undefined ? ',' : options.delimiter;
  if (typeof d !== 'string' || d.length !== 1 || d === '"' || d === '\r' || d === '\n') {
    throw new TypeError('delimiter must be a single character other than ", CR or LF');
  }
  return d;
}

function checkOptions(options) {
  if (options === null || typeof options !== 'object') {
    throw new TypeError('options must be an object');
  }
}

function makeRecord(names, fields) {
  const obj = {};
  names.forEach((name, i) => {
    Object.defineProperty(obj, name, { value: fields[i], enumerable: true, writable: true, configurable: true });
  });
  return obj;
}

function parse(text, options = {}) {
  if (typeof text !== 'string') throw new TypeError('text must be a string');
  checkOptions(options);
  const delim = checkDelimiter(options);
  const skipEmpty = options.skipEmptyLines === true;
  const useHeader = options.header === true;

  if (text.charCodeAt(0) === 0xfeff) text = text.slice(1);
  const n = text.length;
  const records = [];
  let names = null;
  let pos = 0;
  let line = 1;
  let lineStart = 0;

  // Consumes a CRLF, LF or CR at pos and advances line tracking.
  const breakLine = () => {
    pos += text[pos] === '\r' && text[pos + 1] === '\n' ? 2 : 1;
    line++;
    lineStart = pos;
  };
  const atBreak = () => text[pos] === '\r' || text[pos] === '\n';

  while (pos < n) {
    const recLine = line;
    const fields = [];
    const starts = [];
    let emptyLine = false;

    for (;;) {
      starts.push({ line, column: pos - lineStart + 1 });
      if (text[pos] === '"') {
        const open = { line, column: pos - lineStart + 1 };
        let value = '';
        let segment = ++pos;
        for (;;) {
          if (pos >= n) throw new CsvError('unterminated quoted field', open.line, open.column);
          const c = text[pos];
          if (c === '"') {
            value += text.slice(segment, pos);
            if (text[pos + 1] === '"') {
              value += '"';
              pos += 2;
              segment = pos;
            } else {
              pos++;
              break;
            }
          } else if (c === '\r' || c === '\n') {
            value += text.slice(segment, pos);
            const start = pos;
            breakLine();
            value += text.slice(start, pos);
            segment = pos;
          } else {
            pos++;
          }
        }
        if (pos < n && text[pos] !== delim && !atBreak()) {
          throw new CsvError('unexpected character after closing quote', line, pos - lineStart + 1);
        }
        fields.push(value);
      } else {
        const start = pos;
        while (pos < n && text[pos] !== delim && !atBreak()) pos++;
        fields.push(text.slice(start, pos));
        if (fields.length === 1 && pos === start) emptyLine = true;
      }
      if (text[pos] === delim) {
        pos++;
        emptyLine = false;
        continue;
      }
      break;
    }
    if (pos < n) breakLine();

    if (emptyLine && skipEmpty) continue;

    if (!useHeader) {
      records.push(fields);
    } else if (!names) {
      const seen = new Set();
      fields.forEach((name, i) => {
        if (seen.has(name)) {
          throw new CsvError(`duplicate header name ${JSON.stringify(name)}`, starts[i].line, starts[i].column);
        }
        seen.add(name);
      });
      names = fields;
    } else {
      if (fields.length !== names.length) {
        throw new CsvError(`expected ${names.length} fields but found ${fields.length}`, recLine, 1);
      }
      records.push(makeRecord(names, fields));
    }
  }
  return records;
}

function formatValue(value) {
  if (typeof value === 'string') return value;
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (value === null || value === undefined) return '';
  throw new TypeError(`unsupported value type: ${typeof value}`);
}

function stringify(rows, options = {}) {
  if (!Array.isArray(rows)) throw new TypeError('rows must be an array');
  checkOptions(options);
  const delim = checkDelimiter(options);
  const eol = options.eol === undefined ? '\r\n' : options.eol;
  if (eol !== '\r\n' && eol !== '\n') throw new TypeError('eol must be "\\r\\n" or "\\n"');
  const header = options.header;
  if (header !== undefined && !Array.isArray(header)) throw new TypeError('header must be an array of column names');

  const needsQuote = (s) =>
    s.includes(delim) || s.includes('"') || s.includes('\r') || s.includes('\n') ||
    s.startsWith(' ') || s.endsWith(' ');
  const line = (values) => {
    const fields = values.map((v) => {
      const s = formatValue(v);
      return needsQuote(s) ? `"${s.replace(/"/g, '""')}"` : s;
    });
    if (fields.length === 1 && fields[0] === '') return '""';
    return fields.join(delim);
  };

  const lines = [];
  if (header) lines.push(line(header));
  for (const row of rows) {
    if (Array.isArray(row)) {
      lines.push(line(row));
    } else if (header && row !== null && typeof row === 'object') {
      lines.push(line(header.map((name) => (Object.prototype.hasOwnProperty.call(row, name) ? row[name] : undefined))));
    } else {
      throw new TypeError('each row must be an array (or an object when options.header is set)');
    }
  }
  return lines.map((l) => l + eol).join('');
}

module.exports = { parse, stringify, CsvError };

